class DropAddZero : CSharpSyntaxRewriter
{
    public override SyntaxNode? VisitBinaryExpression(BinaryExpressionSyntax node)
    {
        var updated = (BinaryExpressionSyntax)base.VisitBinaryExpression(node)!;
        if (updated.IsKind(SyntaxKind.AddExpression) &&
            updated.Right.IsKind(SyntaxKind.NumericLiteralExpression) &&
            updated.Right.ToString() == "0")
            return updated.Left;                     // x + 0 -> x
        return updated;
    }
}
